    tempC: 232,
    tempFormatted: 'Medium-high direct, 450°F (232°C), grate scrubbed spotless and wiped with an oiled paper towel',
    timeMinMinutes: 8,
    timeMaxMinutes: 12,
    timeFormatted: '8–12 mins (6–8 min skin-down first, 2–3 min flesh-down last)',
    flipAtMinutes: 7,
    internalTempTargetF: 125,
    internalTempTargetFormatted: '125°F–130°F pull for medium (FDA safe target 145°F; the lower pull is the standard restaurant target for moist flake)',
