    state: 'fresh',
    tempF: 200,
    tempC: 93,
    tempFormatted: 'LOW (4–5 hrs)',
    timeMinMinutes: 240,
    timeMaxMinutes: 300,
    timeFormatted: '4–5 hours on LOW',
    flipAtMinutes: 0,
    internalTempTargetF: 160,
    internalTempTargetFormatted: '160°F at the centre of the thickest link (USDA FSIS raw pork sausage minimum)',
