    foodSlug: 'brussels-sprouts-air-fryer',
    appliance: 'air-fryer',
    cutOrPrep: '1 lb fresh Brussels sprouts trimmed and halved cut-side down first, tossed with 1.5 tbsp oil + 1 tsp kosher salt + 1/2 tsp black pepper',
    state: 'fresh',
    tempF: 380,
